func fmtInt(v float64) string {
	s := fmt.Sprintf("%.0f", v)
	var b strings.Builder
	for i, r := range s {
		if i > 0 && (len(s)-i)%3 == 0 {
			b.WriteString(" ")
		}
		b.WriteRune(r)
	}
	return b.String()
}

func token(sel []obce.Resolved) string {
	items := make([]obce.Item, len(sel))
	for i, s := range sel {
		items[i] = s.Item
	}
	return obce.FormatSelection(items)
}

